def write_module(filename, themes):
    with open(filename, "w", encoding="utf-8") as f:
        f.write("# -*- coding: utf-8 -*-\n")
        f.write("themes = [\n")
        for title, icon, vocab, sentence, zh in themes:
            v_str = repr(vocab)
            s_str = repr(sentence)
            z_str = repr(zh)
            t_str = repr(title)
            i_str = repr(icon)
            f.write(f"    ({t_str}, {i_str}, {v_str}, {s_str}, {z_str}),\n")
        f.write("]\n")

