    assert len(sh_adv_themes) == 74, f"sh_adv count: {len(sh_adv_themes)}"
    write_module("curriculum_data_builders/sh_beg.py", sh_beg_themes)
    write_module("curriculum_data_builders/sh_mid.py", sh_mid_themes)
    write_module("curriculum_data_builders/sh_adv.py", sh_adv_themes)
    print("Successfully generated sh_beg.py, sh_mid.py, and sh_adv.py with 74 themes each!")
